void BuildRefractionUV(
      float4 screenPosition,
      float2 distortion,
      out float2 sceneUV)
  {
      uint width;
      uint height;
      gShaderGraphSceneColor.GetDimensions(width, height);

      float2 resolution = max(
          float2(width, height),
          float2(1.0f, 1.0f));

      sceneUV = saturate(
          screenPosition.xy / resolution + distortion);
  }
